@Slf4j
@PluginDescriptor(
	name = "Gielinor Profile Sync",
	legacyDataDirectory = "gielinor-profile-sync",
	internalName = "gielinor-profile-sync",
	description = "Export your character's progress, gear, and bank for personal dashboards and planning tools.",
	tags = {"profile", "export", "json", "progress", "avatar"}
)
public class GielinorProfileSyncPlugin extends Plugin
{
	static final String CONFIG_GROUP = "gielinor-profile-sync";
	private static final String PLUGIN_VERSION = "0.1.5";
	private static final int SCHEMA_VERSION = 1;
	private static final int LOGIN_SETTLE_TICKS = 5;
	private static final int COLLECTION_LOG_ENTRY_TITLE_INDEX = 0;

	@Inject
	private Client client;

	@Inject
	private Gson gson;

	@Inject
	private ItemManager itemManager;

	@Inject
	private GielinorProfileSyncConfig config;

	@Inject
	private ClientThread clientThread;

	private final PohSnapshotTracker pohSnapshots = new PohSnapshotTracker();
	private final HunterRumourSnapshot hunterRumours = new HunterRumourSnapshot();
	private final CollectionLogAccountSnapshots collectionLogSnapshots = new CollectionLogAccountSnapshots();

	private ExecutorService fileExecutor;
	private ProfileExportStore exportStore;
	private volatile Map<String, Object> previousSnapshot = Collections.emptyMap();
	private int ticksLoggedIn;
	private int ticksSinceExport;
	private String lastRsn = "";
	private CachedContainer lastGoodBank;
	private CachedContainer lastGoodInventory;
	private CachedContainer lastGoodEquipment;

	@Provides
	GielinorProfileSyncConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GielinorProfileSyncConfig.class);
	}

	@Override
	protected void startUp()
	{
		exportStore = null;
		fileExecutor = Executors.newSingleThreadExecutor(runnable ->
		{
			Thread thread = new Thread(runnable, CONFIG_GROUP + "-writer");
			thread.setDaemon(true);
			return thread;
		});
		fileExecutor.execute(() ->
		{
			try
			{
				previousSnapshot = getExportStore().readLatest();
			}
			catch (IOException e)
			{
				log.warn("Could not initialize the local profile directory.", e);
			}
		});
		log.info("Gielinor Profile Sync started.");
	}

	@Override
	protected void shutDown()
	{
		if (fileExecutor != null)
		{
			fileExecutor.shutdownNow();
			fileExecutor = null;
		}
		resetSession();
		log.info("Gielinor Profile Sync stopped.");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			pohSnapshots.clearScene();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		observePohObject(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		pohSnapshots.forget(event.getGameObject());
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		observePohObject(event.getDecorativeObject());
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		pohSnapshots.forget(event.getDecorativeObject());
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		observePohObject(event.getWallObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		pohSnapshots.forget(event.getWallObject());
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		observePohObject(event.getGroundObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		pohSnapshots.forget(event.getGroundObject());
	}

	private void observePohObject(TileObject object)
	{
		if (object == null)
		{
			return;
		}
		ObjectComposition composition = client.getObjectDefinition(object.getId());
		pohSnapshots.observe(object, composition);
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.COLLECTION_DRAW_LIST)
		{
			return;
		}
		Player localPlayer = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN
			|| localPlayer == null
			|| client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) != 0)
		{
			return;
		}
		String rsn = localPlayer.getName();
		if (rsn == null || rsn.trim().isEmpty())
		{
			return;
		}

		Widget header = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
		Widget contents = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (header == null || header.getChildren() == null || contents == null || contents.getChildren() == null)
		{
			return;
		}
		Widget titleWidget = header.getChild(COLLECTION_LOG_ENTRY_TITLE_INDEX);
		if (titleWidget == null || titleWidget.getText() == null)
		{
			return;
		}

		List<CollectionLogSnapshot.ItemObservation> items = new ArrayList<>();
		for (Widget child : contents.getChildren())
		{
			if (child == null)
			{
				continue;
			}
			int itemId = child.getItemId();
			if (itemId <= 0)
			{
				continue;
			}
			String itemName = itemManager.getItemComposition(itemId).getName();
			items.add(new CollectionLogSnapshot.ItemObservation(
				itemId,
				itemName,
				child.getOpacity() == 0,
				child.getItemQuantity()
			));
		}

		String category = activeCollectionLogCategory();
		long observedAt = System.currentTimeMillis();
		CollectionLogSnapshot collectionLogSnapshot = collectionLogSnapshots.activate(rsn);
		collectionLogSnapshot.observeUniqueCounts(
			client.getVarpValue(VarPlayerID.COLLECTION_COUNT),
			client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX),
			observedAt
		);
		if (collectionLogSnapshot.observePage(category, Text.removeTags(titleWidget.getText()), items, observedAt))
		{
			ticksSinceExport = Math.max(10, config.exportIntervalTicks());
		}
	}

	private String activeCollectionLogCategory()
	{
		Widget tabs = client.getWidget(InterfaceID.Collection.TABS);
		if (tabs == null || tabs.getStaticChildren() == null)
		{
			return null;
		}
		Widget[] children = tabs.getStaticChildren();
		int activeIndex = client.getVarbitValue(VarbitID.COLLECTION_LAST_TAB);
		if (activeIndex < 0 || activeIndex >= children.length || children[activeIndex] == null)
		{
			return null;
		}
		String rawName = children[activeIndex].getName();
		return rawName == null ? null : Text.removeTags(rawName);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		Player player = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN || player == null || !lastRsn.equals(player.getName()))
		{
			return;
		}
		if (hunterRumours.observe(event.getType(), event.getMessage(), isInHunterBurrows(), System.currentTimeMillis()))
		{
			ticksSinceExport = Math.max(10, config.exportIntervalTicks());
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();
		if (containerId == InventoryID.BANK || containerId == InventoryID.INV || containerId == InventoryID.WORN)
		{
			ticksSinceExport = Math.max(10, config.exportIntervalTicks());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN || player == null)
		{
			ticksLoggedIn = 0;
			ticksSinceExport = 0;
			return;
		}

		String rsn = player.getName();
		if (rsn == null || rsn.trim().isEmpty())
		{
			return;
		}

		if (!rsn.equals(lastRsn))
		{
			resetAccount(rsn);
		}

		ticksLoggedIn++;
		ticksSinceExport++;
		if (ticksLoggedIn < LOGIN_SETTLE_TICKS)
		{
			return;
		}

		int interval = Math.max(10, config.exportIntervalTicks());
		if (ticksSinceExport < interval)
		{
			return;
		}

		ticksSinceExport = 0;
		exportSnapshot(player, rsn);
	}

	private void exportSnapshot(Player player, String rsn)
	{
		long now = System.currentTimeMillis();
		Map<String, Object> snapshot = new LinkedHashMap<>();
		snapshot.put("schemaVersion", SCHEMA_VERSION);
		snapshot.put("version", PLUGIN_VERSION);
		snapshot.put("timestamp", now);
		snapshot.put("timestampIso", Instant.ofEpochMilli(now).toString());
		snapshot.put("source", buildSource());
		snapshot.put("capabilities", Arrays.asList("skills", "quests", "achievementDiaries", "achievementDiaryTaskProgress", "slayerTask", "hunterRumours", "playerOwnedHouse", "playerOwnedHouseLayout", "collectionLogPageObservations", "containers", "grandExchange", "appearance", "playerModel"));
		snapshot.put("rsn", rsn);
		snapshot.put("combatLevel", player.getCombatLevel());
		snapshot.put("totalLevel", calculateTotalLevel());
		snapshot.put("totalXp", calculateTotalXp());
		snapshot.put("skills", buildSkills());
		snapshot.put("appearance", buildAppearance(player));

		CachedContainer inventory = chooseContainer("inventory", buildContainer(InventoryID.INV), lastGoodInventory, now, rsn);
		CachedContainer equipment = chooseContainer("equipment", buildContainer(InventoryID.WORN), lastGoodEquipment, now, rsn);
		CachedContainer bank = chooseContainer("bank", buildContainer(InventoryID.BANK), lastGoodBank, now, rsn);
		lastGoodInventory = inventory;
		lastGoodEquipment = equipment;
		lastGoodBank = bank;

		putContainer(snapshot, "inventory", inventory);
		putContainer(snapshot, "equipment", equipment);
		putContainer(snapshot, "bank", bank);

		long inventoryValue = inventory.loaded ? getLong(inventory.data.get("value")) : 0;
		long equipmentValue = equipment.loaded ? getLong(equipment.data.get("value")) : 0;
		long bankValue = bank.loaded ? getLong(bank.data.get("value")) : 0;
		snapshot.put("inventoryValue", inventoryValue);
		snapshot.put("equipmentValue", equipmentValue);
		snapshot.put("bankValue", bankValue);
		snapshot.put("bankItemCount", bank.loaded ? getInt(bank.data.get("itemCount")) : 0);
		snapshot.put("carriedValue", inventoryValue + equipmentValue);
		snapshot.put("knownAccountValue", inventoryValue + equipmentValue + bankValue);

		Map<String, Object> grandExchange = buildGrandExchangeOffers();
		snapshot.put("grandExchange", grandExchange);
		snapshot.put("grandExchangeAccountValueEstimate", getLong(grandExchange.get("accountValueEstimate")));
		snapshot.put("quests", buildQuests());
		snapshot.put("achievementDiaries", AchievementDiarySnapshot.build(client::getVarbitValue));
		if (rsn.equals(previousSnapshot.get("rsn")))
		{
			hunterRumours.restore(previousSnapshot.get("hunterRumours"));
			pohSnapshots.restore(previousSnapshot.get("playerOwnedHouse"));
		}
		snapshot.put("playerOwnedHouse", pohSnapshots.snapshot(
			now,
			client.getVarbitValue(VarbitID.POH_BUILDING_MODE) > 0,
			client.getVarbitValue(VarbitID.POH_HOUSE_LOCATION),
			client.getVarbitValue(VarbitID.POH_HOUSE_STYLE),
			client.getVarbitValue(VarbitID.POH_HOUSE_SIZE),
			client.isInInstancedRegion() ? client.getInstanceTemplateChunks() : null
		));
		snapshot.put("hunterRumours", hunterRumours.snapshot());
		snapshot.put("slayer", SlayerTaskSnapshot.build(client, now));
		snapshot.put("collectionLog", collectionLogSnapshots.current().toMap());

		ExecutorService executor = fileExecutor;
		if (executor != null)
		{
			executor.execute(() -> writeSnapshot(rsn, snapshot));
		}
	}

	private Map<String, Object> buildSource()
	{
		Map<String, Object> source = new LinkedHashMap<>();
		source.put("name", "Gielinor Profile Sync");
		source.put("version", PLUGIN_VERSION);
		source.put("transport", "local-file");
		source.put("networkRequests", false);
		return source;
	}

	private ProfileExportStore getExportStore() throws IOException
	{
		if (exportStore == null)
		{
			exportStore = new ProfileExportStore(gson, getPluginDirectory());
		}
		return exportStore;
	}

	private boolean isInHunterBurrows()
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return false;
		}
		WorldPoint location = localPlayer.getWorldLocation();
		return location.getPlane() == 0
			&& location.getX() >= 1549 && location.getX() <= 1565
			&& location.getY() >= 9449 && location.getY() <= 9464;
	}

	private void writeSnapshot(String rsn, Map<String, Object> snapshot)
	{
		try
		{
			ProfileExportStore store = getExportStore();
			Map<String, Object> accountSnapshot = store.readAccount(rsn);
			Object mergedCollectionLog = CollectionLogAccountSnapshots.mergeForExport(
				accountSnapshot.get("collectionLog"), snapshot.get("collectionLog"));
			snapshot.put("collectionLog", mergedCollectionLog);
			store.write(rsn, snapshot);
			clientThread.invokeLater(() -> collectionLogSnapshots.merge(rsn, mergedCollectionLog));
			previousSnapshot = snapshot;
			log.debug("Wrote local profile snapshot for {}.", rsn);
		}
		catch (IOException e)
		{
			log.warn("Could not write the local profile snapshot.", e);
		}
	}

	private Map<String, Object> buildSkills()
	{
		Map<String, Object> skills = new LinkedHashMap<>();
		for (Skill skill : Skill.values())
		{
			Map<String, Object> data = new LinkedHashMap<>();
			data.put("level", client.getRealSkillLevel(skill));
			data.put("boostedLevel", client.getBoostedSkillLevel(skill));
			data.put("xp", client.getSkillExperience(skill));
			skills.put(skill.getName(), data);
		}
		return skills;
	}

	private int calculateTotalLevel()
	{
		int total = 0;
		for (Skill skill : Skill.values())
		{
			total += client.getRealSkillLevel(skill);
		}
		return total;
	}

	private long calculateTotalXp()
	{
		long total = 0;
		for (Skill skill : Skill.values())
		{
			total += client.getSkillExperience(skill);
		}
		return total;
	}

	private Map<String, Object> buildAppearance(Player player)
	{
		Map<String, Object> appearance = new LinkedHashMap<>();
		PlayerComposition composition = player.getPlayerComposition();
		appearance.put("loaded", composition != null);
		if (composition == null)
		{
			return appearance;
		}

		appearance.put("gender", composition.getGender());
		appearance.put("colors", toIntegerList(composition.getColors()));
		appearance.put("equipmentIds", toIntegerList(composition.getEquipmentIds()));
		appearance.put("transformedNpcId", composition.getTransformedNpcId());
		Map<String, Object> model = PlayerModelSnapshot.from(player.getModel());
		if (model != null)
		{
			appearance.put("model", model);
		}

		Map<String, Object> slots = new LinkedHashMap<>();
		for (KitType kitType : KitType.values())
		{
			int rawId = composition.getEquipmentId(kitType);
			Map<String, Object> slot = new LinkedHashMap<>();
			slot.put("rawId", rawId);
			if (rawId >= PlayerComposition.ITEM_OFFSET)
			{
				slot.put("kind", "item");
				slot.put("id", rawId - PlayerComposition.ITEM_OFFSET);
			}
			else if (rawId >= PlayerComposition.KIT_OFFSET)
			{
				slot.put("kind", "kit");
				slot.put("id", rawId - PlayerComposition.KIT_OFFSET);
			}
			else
			{
				slot.put("kind", "empty");
				slot.put("id", -1);
			}
			slots.put(kitType.name().toLowerCase(), slot);
		}
		appearance.put("slots", slots);
		return appearance;
	}

	private List<Integer> toIntegerList(int[] values)
	{
		List<Integer> output = new ArrayList<>(values.length);
		for (int value : values)
		{
			output.add(value);
		}
		return output;
	}

	private Map<String, Object> buildContainer(int inventoryId)
	{
		Map<String, Object> result = new LinkedHashMap<>();
		ItemContainer container = client.getItemContainer(inventoryId);
		boolean loaded = container != null;
		result.put("loaded", loaded);

		long totalValue = 0;
		int itemCount = 0;
		Map<String, Object> items = new LinkedHashMap<>();
		if (container != null)
		{
			Item[] containerItems = container.getItems();
			for (int slotIndex = 0; slotIndex < containerItems.length; slotIndex++)
			{
				Item item = containerItems[slotIndex];
				if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
				{
					continue;
				}

				int id = item.getId();
				int quantity = item.getQuantity();
				long price = itemManager.getItemPrice(id);
				long value = (long) price * quantity;
				Map<String, Object> itemData = new LinkedHashMap<>();
				itemData.put("slot", slotIndex);
				itemData.put("id", id);
				itemData.put("name", itemManager.getItemComposition(id).getName());
				itemData.put("quantity", quantity);
				itemData.put("price", price);
				itemData.put("value", value);
				items.put(String.valueOf(slotIndex), itemData);
				totalValue += value;
				itemCount++;
			}
		}

		result.put("value", totalValue);
		result.put("itemCount", itemCount);
		result.put("items", items);
		return result;
	}

	private CachedContainer chooseContainer(String key, Map<String, Object> current, CachedContainer memory, long now, String rsn)
	{
		if (Boolean.TRUE.equals(current.get("loaded")))
		{
			return new CachedContainer(current, true, false, now);
		}
		if (memory != null && memory.loaded)
		{
			return new CachedContainer(memory.data, true, true, memory.lastSeenTimestamp);
		}

		Map<String, Object> previous = previousSnapshot;
		if (rsn.equals(previous.get("rsn")) && previous.get(key) instanceof Map)
		{
			@SuppressWarnings("unchecked")
			Map<String, Object> previousContainer = (Map<String, Object>) previous.get(key);
			if (Boolean.TRUE.equals(previousContainer.get("loaded")))
			{
				long lastSeen = getLong(previous.get(key + "LastSeenTimestamp"));
				if (lastSeen <= 0)
				{
					lastSeen = getLong(previous.get("timestamp"));
				}
				return new CachedContainer(previousContainer, true, true, lastSeen);
			}
		}

		return new CachedContainer(current, false, false, 0);
	}

	private void putContainer(Map<String, Object> snapshot, String key, CachedContainer container)
	{
		snapshot.put(key, container.data);
		snapshot.put(key + "Loaded", container.loaded);
		snapshot.put(key + "FromCache", container.fromCache);
		snapshot.put(key + "LastSeenTimestamp", container.lastSeenTimestamp);
	}

	private Map<String, Object> buildGrandExchangeOffers()
	{
		Map<String, Object> result = new LinkedHashMap<>();
		Map<String, Object> offersOut = new LinkedHashMap<>();
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		result.put("loaded", offers != null);
		int activeCount = 0;
		long listedValueEstimate = 0;
		long accountValueEstimate = 0;

		if (offers != null)
		{
			for (int slotIndex = 0; slotIndex < offers.length; slotIndex++)
			{
				GrandExchangeOffer offer = offers[slotIndex];
				if (offer == null || offer.getState() == null || "EMPTY".equals(offer.getState().name()))
				{
					continue;
				}

				int itemId = offer.getItemId();
				long marketPrice = itemId > 0 ? itemManager.getItemPrice(itemId) : 0;
				int totalQuantity = offer.getTotalQuantity();
				int completedQuantity = offer.getQuantitySold();
				int remainingQuantity = Math.max(0, totalQuantity - completedQuantity);
				String state = offer.getState().name();
				long offerListedValue = (long) offer.getPrice() * totalQuantity;
				long offerAccountValue = estimateGrandExchangeValue(state, marketPrice, offer, completedQuantity, remainingQuantity);

				Map<String, Object> offerOut = new LinkedHashMap<>();
				offerOut.put("slot", slotIndex);
				offerOut.put("state", state);
				offerOut.put("itemId", itemId);
				offerOut.put("itemName", itemId > 0 ? itemManager.getItemComposition(itemId).getName() : "");
				offerOut.put("listedPrice", offer.getPrice());
				offerOut.put("marketPrice", marketPrice);
				offerOut.put("totalQuantity", totalQuantity);
				offerOut.put("completedQuantity", completedQuantity);
				offerOut.put("remainingQuantity", remainingQuantity);
				offerOut.put("spent", offer.getSpent());
				offerOut.put("listedValueEstimate", offerListedValue);
				offerOut.put("accountValueEstimate", offerAccountValue);
				offersOut.put(String.valueOf(slotIndex), offerOut);
				activeCount++;
				listedValueEstimate += offerListedValue;
				accountValueEstimate += offerAccountValue;
			}
		}

		result.put("activeCount", activeCount);
		result.put("listedValueEstimate", listedValueEstimate);
		result.put("accountValueEstimate", accountValueEstimate);
		result.put("offers", offersOut);
		return result;
	}

	private long estimateGrandExchangeValue(String state, long marketPrice, GrandExchangeOffer offer, int completed, int remaining)
	{
		if (state.contains("SELL"))
		{
			return (long) offer.getSpent() + (long) marketPrice * remaining;
		}
		if (state.contains("BUY"))
		{
			return (long) marketPrice * completed + (long) offer.getPrice() * remaining;
		}
		return (long) marketPrice * offer.getTotalQuantity();
	}

	private Map<String, Object> buildQuests()
	{
		Map<String, Object> result = new LinkedHashMap<>();
		Map<String, Object> entries = new LinkedHashMap<>();
		int notStarted = 0;
		int inProgress = 0;
		int finished = 0;
		int unknown = 0;

		for (Quest quest : Quest.values())
		{
			QuestState state;
			try
			{
				state = quest.getState(client);
			}
			catch (RuntimeException e)
			{
				state = null;
			}

			String stateName = state != null ? state.name() : "UNKNOWN";
			if (state == QuestState.NOT_STARTED)
			{
				notStarted++;
			}
			else if (state == QuestState.IN_PROGRESS)
			{
				inProgress++;
			}
			else if (state == QuestState.FINISHED)
			{
				finished++;
			}
			else
			{
				unknown++;
			}

			Map<String, Object> data = new LinkedHashMap<>();
			data.put("name", quest.getName());
			data.put("state", stateName);
			entries.put(quest.name(), data);
		}

		result.put("notStarted", notStarted);
		result.put("inProgress", inProgress);
		result.put("finished", finished);
		result.put("unknown", unknown);
		result.put("total", entries.size());
		result.put("entries", entries);
		return result;
	}

	private long getLong(Object value)
	{
		return value instanceof Number ? ((Number) value).longValue() : 0L;
	}

	private int getInt(Object value)
	{
		return value instanceof Number ? ((Number) value).intValue() : 0;
	}

	private void resetSession()
	{
		ticksLoggedIn = 0;
		ticksSinceExport = 0;
		lastRsn = "";
		collectionLogSnapshots.deactivate();
		hunterRumours.resetAccount();
		pohSnapshots.resetAccount();
		lastGoodBank = null;
		lastGoodInventory = null;
		lastGoodEquipment = null;
	}

	private void resetAccount(String rsn)
	{
		hunterRumours.resetAccount();
		pohSnapshots.resetAccount();
		lastRsn = rsn;
		collectionLogSnapshots.activate(rsn);
		lastGoodBank = null;
		lastGoodInventory = null;
		lastGoodEquipment = null;
		ticksSinceExport = Math.max(10, config.exportIntervalTicks());
	}

	private static final class CachedContainer
	{
		private final Map<String, Object> data;
		private final boolean loaded;
		private final boolean fromCache;
		private final long lastSeenTimestamp;

		private CachedContainer(Map<String, Object> data, boolean loaded, boolean fromCache, long lastSeenTimestamp)
		{
			this.data = data;
			this.loaded = loaded;
			this.fromCache = fromCache;
			this.lastSeenTimestamp = lastSeenTimestamp;
		}
	}
}

package org.gielinor.profilesync;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.NpcID;

/**
 * Retains Hunter Rumour evidence observed in the game's own dialogue and
 * Quetzal whistle messages. RuneLite does not expose a complete server-backed
 * assignment variable, so unobserved masters and completion totals stay
 * unknown instead of being inferred from inventory or Hunter XP.
 */
final class HunterRumourSnapshot
{
	private static final String COVERAGE = "observed-dialogue-and-whistle";
	private static final String SOURCE = "RuneLite Hunter Guild dialogue and Quetzal whistle observations";
	private static final String RARE_PIECE_MESSAGE = "you find a rare piece of the creature! you should take it back to the hunter guild.";
	private static final List<HunterDefinition> HUNTERS = Arrays.asList(
		new HunterDefinition("wolf", NpcID.HG_WOLF, "Wolf", "Guild Hunter Wolf", "master"),
		new HunterDefinition("teco", NpcID.HG_TECO, "Teco", "Guild Hunter Teco", "expert"),
		new HunterDefinition("aco", NpcID.HG_ACO, "Aco", "Guild Hunter Aco", "expert"),
		new HunterDefinition("cervus", NpcID.HG_CERVUS, "Cervus", "Guild Hunter Cervus", "adept"),
		new HunterDefinition("ornus", NpcID.HG_ORNUS, "Ornus", "Guild Hunter Ornus", "adept"),
		new HunterDefinition("gilman", NpcID.HG_GILMAN, "Gilman", "Huntmaster Gilman", "novice")
	);
	private static final List<RumourDefinition> RUMOURS = rumourDefinitions();

	private final Map<String, Assignment> assignments = new LinkedHashMap<>();
	private String activeHunterKey;
	private RumourDefinition activeRumour;
	private String activeObservationSource;
	private long activeObservedAt;
	private boolean currentComplete;
	private boolean knownNoAssignment;
	private long lastSeenTimestamp;
	private boolean restored;

	boolean observe(ChatMessageType type, String rawMessage, boolean inHunterBurrows, long observedAt)
	{
		String message = normalized(rawMessage);
		if (message.isEmpty())
		{
			return false;
		}

		if (type == ChatMessageType.GAMEMESSAGE)
		{
			if (message.contains("your current rumour target is"))
			{
				HunterDefinition hunter = referencedHunter(message);
				RumourDefinition rumour = referencedRumour(message);
				if (rumour == null)
				{
					return false;
				}
				return hunter == null
					? activateUnattributed(rumour, "quetzal-whistle", observedAt)
					: activate(hunter, rumour, "quetzal-whistle", observedAt);
			}
			if (message.equals(RARE_PIECE_MESSAGE) && activeRumour != null && !currentComplete)
			{
				currentComplete = true;
				markObserved(observedAt);
				return true;
			}
			return false;
		}

		if (type != ChatMessageType.DIALOG || !inHunterBurrows)
		{
			return false;
		}

		HunterDefinition speaker = speakingHunter(message);
		if (speaker == null)
		{
			return false;
		}
		String dialogue = message.substring(message.indexOf('|') + 1).trim();
		if (dialogue.contains("would you like another rumour?")
			|| dialogue.contains("here's your reward.")
			|| dialogue.contains("another one done?"))
		{
			if (activeHunterKey != null)
			{
				assignments.remove(activeHunterKey);
			}
			activeHunterKey = null;
			activeRumour = null;
			activeObservationSource = null;
			activeObservedAt = 0L;
			currentComplete = false;
			knownNoAssignment = true;
			markObserved(observedAt);
			return true;
		}
		if (dialogue.contains("stopped off for a bit of hunting first"))
		{
			return false;
		}

		RumourDefinition rumour = referencedRumour(dialogue);
		if (rumour == null)
		{
			return false;
		}
		HunterDefinition referenced = referencedHunter(dialogue);
		HunterDefinition assignmentHunter = referenced == null ? speaker : referenced;
		boolean noviceReassignmentOffer = dialogue.contains("would you prefer that one, or a new one entirely");
		assignments.put(assignmentHunter.key, new Assignment(assignmentHunter, rumour, "hunter-dialogue", observedAt));
		if (!noviceReassignmentOffer)
		{
			activeHunterKey = assignmentHunter.key;
			activeRumour = rumour;
			activeObservationSource = "hunter-dialogue";
			activeObservedAt = observedAt;
			currentComplete = false;
			knownNoAssignment = false;
		}
		markObserved(observedAt);
		return true;
	}

	void restore(Object value)
	{
		if (lastSeenTimestamp > 0 || !(value instanceof Map))
		{
			return;
		}
		Map<?, ?> candidate = (Map<?, ?>) value;
		if (!Boolean.TRUE.equals(candidate.get("loaded")) || !(candidate.get("assignments") instanceof List))
		{
			return;
		}
		for (Object rawAssignment : (List<?>) candidate.get("assignments"))
		{
			if (!(rawAssignment instanceof Map))
			{
				continue;
			}
			Map<?, ?> entry = (Map<?, ?>) rawAssignment;
			HunterDefinition hunter = hunterByKey(string(entry.get("hunterKey")));
			RumourDefinition rumour = rumourByName(string(entry.get("rumour")));
			if (hunter == null || rumour == null)
			{
				continue;
			}
			long observedAt = number(entry.get("observedAt"));
			assignments.put(hunter.key, new Assignment(hunter, rumour, string(entry.get("observationSource")), observedAt));
		}
		Object rawCurrent = candidate.get("current");
		if (rawCurrent instanceof Map)
		{
			Map<?, ?> current = (Map<?, ?>) rawCurrent;
			RumourDefinition rumour = rumourByName(string(current.get("rumour")));
			HunterDefinition hunter = hunterByKey(string(current.get("hunterKey")));
			if (rumour != null)
			{
				activeRumour = rumour;
				activeHunterKey = hunter == null ? null : hunter.key;
				activeObservationSource = retainedSource(current.get("observationSource"));
				activeObservedAt = number(current.get("observedAt"));
				currentComplete = Boolean.TRUE.equals(current.get("complete"));
				if (hunter != null && !assignments.containsKey(hunter.key))
				{
					assignments.put(hunter.key, new Assignment(hunter, rumour, activeObservationSource, activeObservedAt));
				}
			}
		}
		knownNoAssignment = activeRumour == null && "none".equals(candidate.get("status"));
		lastSeenTimestamp = number(candidate.get("lastSeenTimestamp"));
		if (lastSeenTimestamp <= 0)
		{
			lastSeenTimestamp = isoMillis(string(candidate.get("lastSeenTimestampIso")));
		}
		restored = lastSeenTimestamp > 0;
	}

	void resetAccount()
	{
		assignments.clear();
		activeHunterKey = null;
		activeRumour = null;
		activeObservationSource = null;
		activeObservedAt = 0L;
		currentComplete = false;
		knownNoAssignment = false;
		lastSeenTimestamp = 0L;
		restored = false;
	}

	Map<String, Object> snapshot()
	{
		Map<String, Object> output = new LinkedHashMap<>();
		output.put("schemaVersion", 1);
		output.put("source", SOURCE);
		output.put("sourceVersion", "hunter-rumours-observation-v3");
		output.put("coverage", COVERAGE);
		output.put("loaded", lastSeenTimestamp > 0);
		output.put("fromCache", restored && lastSeenTimestamp > 0);
		output.put("lastSeenTimestamp", lastSeenTimestamp);
		output.put("lastSeenTimestampIso", lastSeenTimestamp > 0 ? Instant.ofEpochMilli(lastSeenTimestamp).toString() : null);
		output.put("status", status());

		List<Map<String, Object>> observedAssignments = new ArrayList<>();
		for (Assignment assignment : assignments.values())
		{
			observedAssignments.add(assignment.toMap(
				assignment.hunter.key.equals(activeHunterKey),
				assignment.hunter.key.equals(activeHunterKey) && currentComplete
			));
		}
		output.put("assignments", observedAssignments);
		output.put("current", activeRumour == null ? null : currentToMap());
		output.put("completionCount", null);
		output.put("unobservedAssignmentsAreUnknown", true);
		return output;
	}

	private boolean activate(HunterDefinition hunter, RumourDefinition rumour, String source, long observedAt)
	{
		Assignment previous = assignments.get(hunter.key);
		boolean changed = previous == null || !previous.rumour.name.equals(rumour.name)
			|| !hunter.key.equals(activeHunterKey) || currentComplete;
		assignments.put(hunter.key, new Assignment(hunter, rumour, source, observedAt));
		activeHunterKey = hunter.key;
		activeRumour = rumour;
		activeObservationSource = source;
		activeObservedAt = observedAt;
		currentComplete = false;
		knownNoAssignment = false;
		markObserved(observedAt);
		return changed || observedAt > 0;
	}

	private boolean activateUnattributed(RumourDefinition rumour, String source, long observedAt)
	{
		boolean changed = activeHunterKey != null || activeRumour == null
			|| !activeRumour.name.equals(rumour.name) || currentComplete;
		activeHunterKey = null;
		activeRumour = rumour;
		activeObservationSource = source;
		activeObservedAt = observedAt;
		currentComplete = false;
		knownNoAssignment = false;
		markObserved(observedAt);
		return changed || observedAt > 0;
	}

	private Map<String, Object> currentToMap()
	{
		Map<String, Object> value = new LinkedHashMap<>();
		HunterDefinition hunter = hunterByKey(activeHunterKey);
		if (hunter != null)
		{
			value.put("hunterKey", hunter.key);
			value.put("hunterNpcId", hunter.npcId);
			value.put("hunterName", hunter.name);
			value.put("hunterTier", hunter.tier);
		}
		value.put("rumour", activeRumour.name);
		value.put("active", true);
		value.put("complete", currentComplete);
		value.put("observationSource", retainedSource(activeObservationSource));
		value.put("observedAt", activeObservedAt);
		return value;
	}

	private void markObserved(long observedAt)
	{
		lastSeenTimestamp = Math.max(1L, observedAt);
		restored = false;
	}

	private String status()
	{
		if (lastSeenTimestamp <= 0)
		{
			return "unavailable";
		}
		if (activeRumour != null)
		{
			return currentComplete ? "complete" : "active";
		}
		return knownNoAssignment ? "none" : "unavailable";
	}

	private static HunterDefinition speakingHunter(String message)
	{
		int separator = message.indexOf('|');
		if (separator < 0)
		{
			return null;
		}
		String speaker = message.substring(0, separator).trim();
		for (HunterDefinition hunter : HUNTERS)
		{
			String name = hunter.speakerName.toLowerCase(Locale.ROOT);
			if (speaker.equals(name) || speaker.equals(name + " (" + hunter.tier + ")"))
			{
				return hunter;
			}
		}
		return null;
	}

	private static HunterDefinition referencedHunter(String message)
	{
		for (HunterDefinition hunter : HUNTERS)
		{
			if (message.contains(hunter.name.toLowerCase(Locale.ROOT)))
			{
				return hunter;
			}
		}
		return null;
	}

	private static RumourDefinition referencedRumour(String message)
	{
		for (RumourDefinition rumour : RUMOURS)
		{
			for (String phrase : rumour.phrases)
			{
				if (message.contains(phrase))
				{
					return rumour;
				}
			}
		}
		return null;
	}

	private static HunterDefinition hunterByKey(String key)
	{
		for (HunterDefinition hunter : HUNTERS)
		{
			if (hunter.key.equals(key))
			{
				return hunter;
			}
		}
		return null;
	}

	private static RumourDefinition rumourByName(String name)
	{
		for (RumourDefinition rumour : RUMOURS)
		{
			if (rumour.name.equalsIgnoreCase(name))
			{
				return rumour;
			}
		}
		return null;
	}

	private static List<RumourDefinition> rumourDefinitions()
	{
		List<RumourDefinition> values = new ArrayList<>(Arrays.asList(
			new RumourDefinition("Barb-tailed kebbit"), new RumourDefinition("Black warlock"),
			new RumourDefinition("Carnivorous chinchompa", "red chinchompa"), new RumourDefinition("Dashing kebbit"),
			new RumourDefinition("Dark kebbit"), new RumourDefinition("Embertailed jerboa"),
			new RumourDefinition("Grey chinchompa"), new RumourDefinition("Herbiboar"),
			new RumourDefinition("Horned graahk"), new RumourDefinition("Moonlight antelope"),
			new RumourDefinition("Moonlight moth"), new RumourDefinition("Orange salamander"),
			new RumourDefinition("Prickly kebbit"), new RumourDefinition("Pyre fox"),
			new RumourDefinition("Razor-backed kebbit"), new RumourDefinition("Red salamander"),
			new RumourDefinition("Sabre-toothed kebbit"), new RumourDefinition("Sabre-toothed kyatt"),
			new RumourDefinition("Sapphire glacialis"), new RumourDefinition("Snowy knight"),
			new RumourDefinition("Spined larupia"), new RumourDefinition("Spotted kebbit"),
			new RumourDefinition("Sunlight antelope"), new RumourDefinition("Sunlight moth"),
			new RumourDefinition("Swamp lizard"), new RumourDefinition("Tecu salamander"),
			new RumourDefinition("Tropical wagtail"), new RumourDefinition("Wild kebbit"),
			new RumourDefinition("Wyrmscraig goat")
		));
		values.sort(Comparator.comparingInt((RumourDefinition value) -> value.longestPhrase()).reversed());
		return values;
	}

	private static String normalized(String value)
	{
		return value == null ? "" : value.replaceAll("(?i)<br\\s*/?>", " ")
			.replaceAll("<[^>]*>", "")
			.replace('’', '\'')
			.replaceAll("\\s+", " ")
			.trim()
			.toLowerCase(Locale.ROOT);
	}

	private static String string(Object value)
	{
		return value instanceof String ? (String) value : "";
	}

	private static String retainedSource(Object value)
	{
		String source = string(value);
		return source.isEmpty() ? "retained-observation" : source;
	}

	private static long number(Object value)
	{
		return value instanceof Number ? ((Number) value).longValue() : 0L;
	}

	private static long isoMillis(String value)
	{
		try
		{
			return value.isEmpty() ? 0L : Instant.parse(value).toEpochMilli();
		}
		catch (RuntimeException exception)
		{
			return 0L;
		}
	}

	private static final class HunterDefinition
	{
		private final String key;
		private final int npcId;
		private final String name;
		private final String speakerName;
		private final String tier;

		private HunterDefinition(String key, int npcId, String name, String speakerName, String tier)
		{
			this.key = key;
			this.npcId = npcId;
			this.name = name;
			this.speakerName = speakerName;
			this.tier = tier;
		}
	}

	private static final class RumourDefinition
	{
		private final String name;
		private final List<String> phrases;

		private RumourDefinition(String name, String... aliases)
		{
			this.name = name;
			this.phrases = new ArrayList<>();
			this.phrases.add(name.toLowerCase(Locale.ROOT));
			for (String alias : aliases)
			{
				this.phrases.add(alias.toLowerCase(Locale.ROOT));
			}
		}

		private int longestPhrase()
		{
			return phrases.stream().mapToInt(String::length).max().orElse(0);
		}
	}

	private static final class Assignment
	{
		private final HunterDefinition hunter;
		private final RumourDefinition rumour;
		private final String observationSource;
		private final long observedAt;

		private Assignment(HunterDefinition hunter, RumourDefinition rumour, String observationSource, long observedAt)
		{
			this.hunter = hunter;
			this.rumour = rumour;
			this.observationSource = observationSource == null || observationSource.isEmpty() ? "retained-observation" : observationSource;
			this.observedAt = observedAt;
		}

		private Map<String, Object> toMap(boolean active, boolean complete)
		{
			Map<String, Object> value = new LinkedHashMap<>();
			value.put("hunterKey", hunter.key);
			value.put("hunterNpcId", hunter.npcId);
			value.put("hunterName", hunter.name);
			value.put("hunterTier", hunter.tier);
			value.put("rumour", rumour.name);
			value.put("active", active);
			value.put("complete", complete);
			value.put("observationSource", observationSource);
			value.put("observedAt", observedAt);
			return value;
		}
	}
}

package org.gielinor.profilesync;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Model;

final class PlayerModelSnapshot
{
	private static final int MODEL_SCHEMA_VERSION = 1;

	private PlayerModelSnapshot()
	{
	}

	static Map<String, Object> from(Model model)
	{
		if (model == null)
		{
			return null;
		}

		return encode(
			model.getVerticesCount(),
			model.getVerticesX(),
			model.getVerticesY(),
			model.getVerticesZ(),
			model.getFaceCount(),
			model.getFaceIndices1(),
			model.getFaceIndices2(),
			model.getFaceIndices3(),
			model.getFaceColors1(),
			model.getFaceColors2(),
			model.getFaceColors3(),
			model.getFaceTransparencies(),
			model.getFaceTextures());
	}

	static Map<String, Object> encode(
		int vertexCount,
		float[] verticesX,
		float[] verticesY,
		float[] verticesZ,
		int faceCount,
		int[] faces1,
		int[] faces2,
		int[] faces3,
		int[] colors1,
		int[] colors2,
		int[] colors3,
		byte[] transparencies,
		short[] textures)
	{
		if (vertexCount <= 0 || faceCount <= 0 ||
			!hasLength(verticesX, vertexCount) ||
			!hasLength(verticesY, vertexCount) ||
			!hasLength(verticesZ, vertexCount) ||
			!hasLength(faces1, faceCount) ||
			!hasLength(faces2, faceCount) ||
			!hasLength(faces3, faceCount) ||
			!hasLength(colors1, faceCount) ||
			!hasLength(colors2, faceCount) ||
			!hasLength(colors3, faceCount))
		{
			return null;
		}

		Map<String, Object> output = new LinkedHashMap<>();
		output.put("schemaVersion", MODEL_SCHEMA_VERSION);
		output.put("vertexCount", vertexCount);
		output.put("faceCount", faceCount);
		output.put("verticesX", roundedCopy(verticesX, vertexCount));
		output.put("verticesY", roundedCopy(verticesY, vertexCount));
		output.put("verticesZ", roundedCopy(verticesZ, vertexCount));
		output.put("faces1", Arrays.copyOf(faces1, faceCount));
		output.put("faces2", Arrays.copyOf(faces2, faceCount));
		output.put("faces3", Arrays.copyOf(faces3, faceCount));
		output.put("colors1", Arrays.copyOf(colors1, faceCount));
		output.put("colors2", Arrays.copyOf(colors2, faceCount));
		output.put("colors3", Arrays.copyOf(colors3, faceCount));
		if (hasLength(transparencies, faceCount))
		{
			output.put("transparencies", unsignedCopy(transparencies, faceCount));
		}
		if (hasLength(textures, faceCount))
		{
			output.put("textures", integerCopy(textures, faceCount));
		}
		return output;
	}

	private static boolean hasLength(float[] values, int length)
	{
		return values != null && values.length >= length;
	}

	private static boolean hasLength(int[] values, int length)
	{
		return values != null && values.length >= length;
	}

	private static boolean hasLength(byte[] values, int length)
	{
		return values != null && values.length >= length;
	}

	private static boolean hasLength(short[] values, int length)
	{
		return values != null && values.length >= length;
	}

	private static int[] roundedCopy(float[] values, int length)
	{
		int[] output = new int[length];
		for (int index = 0; index < length; index++)
		{
			output[index] = Math.round(values[index]);
		}
		return output;
	}

	private static int[] unsignedCopy(byte[] values, int length)
	{
		int[] output = new int[length];
		for (int index = 0; index < length; index++)
		{
			output[index] = Byte.toUnsignedInt(values[index]);
		}
		return output;
	}

	private static int[] integerCopy(short[] values, int length)
	{
		int[] output = new int[length];
		for (int index = 0; index < length; index++)
		{
			output[index] = values[index];
		}
		return output;
	}
}

package org.gielinor.profilesync;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ObjectComposition;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.ObjectID;

/**
 * Retains a privacy-safe inspection of the player's own house. An inspection is
 * authoritative only while building mode is active and the POH exit portal is
 * present; this avoids mistaking another player's house for the account's POH.
 */
final class PohSnapshotTracker
{
	private final Map<Object, Furniture> sceneFurniture = new IdentityHashMap<>();
	private boolean exitPortalObserved;
	private int exitPortalSceneX;
	private int exitPortalSceneY;
	private int exitPortalPlane;
	private volatile Map<String, Object> lastInspection;

	void observe(TileObject object, ObjectComposition composition)
	{
		if (object == null)
		{
			return;
		}
		if (object.getId() == ObjectID.POH_EXIT_PORTAL)
		{
			exitPortalObserved = true;
			LocalPoint location = object.getLocalLocation();
			exitPortalSceneX = location.getSceneX();
			exitPortalSceneY = location.getSceneY();
			exitPortalPlane = object.getPlane();
		}
		LocalPoint location = object.getLocalLocation();
		Furniture furniture = Furniture.from(
			object.getId(),
			composition,
			location.getSceneX(),
			location.getSceneY(),
			object.getPlane()
		);
		if (furniture != null)
		{
			sceneFurniture.put(object, furniture);
		}
	}

	void observeForTest(Object key, int objectId, String name, String... actions)
	{
		observeForTest(key, objectId, name, 0, 0, 0, actions);
	}

	void observeForTest(Object key, int objectId, String name, int sceneX, int sceneY, int plane, String... actions)
	{
		if (objectId == ObjectID.POH_EXIT_PORTAL)
		{
			exitPortalObserved = true;
			exitPortalSceneX = sceneX;
			exitPortalSceneY = sceneY;
			exitPortalPlane = plane;
		}
		Furniture furniture = Furniture.from(objectId, name, sceneX, sceneY, plane, actions);
		if (furniture != null)
		{
			sceneFurniture.put(key, furniture);
		}
	}

	void forget(TileObject object)
	{
		if (object != null)
		{
			sceneFurniture.remove(object);
			if (object.getId() == ObjectID.POH_EXIT_PORTAL)
			{
				exitPortalObserved = false;
				exitPortalSceneX = 0;
				exitPortalSceneY = 0;
				exitPortalPlane = 0;
			}
		}
	}

	void clearScene()
	{
		sceneFurniture.clear();
		exitPortalObserved = false;
		exitPortalSceneX = 0;
		exitPortalSceneY = 0;
		exitPortalPlane = 0;
	}

	void resetAccount()
	{
		lastInspection = null;
	}

	void restore(Object value)
	{
		if (lastInspection != null)
		{
			return;
		}
		if (!(value instanceof Map))
		{
			return;
		}
		@SuppressWarnings("unchecked")
		Map<String, Object> candidate = (Map<String, Object>) value;
		if (Boolean.TRUE.equals(candidate.get("loaded")) && "building-mode".equals(candidate.get("ownershipEvidence"))
			&& candidate.get("furniture") instanceof List)
		{
			lastInspection = new LinkedHashMap<>(candidate);
		}
	}

	Map<String, Object> snapshot(
		long timestamp,
		boolean buildingMode,
		int houseLocation,
		int houseStyle,
		int houseSize,
		int[][][] instanceTemplateChunks
	)
	{
		if (buildingMode && exitPortalObserved)
		{
			List<Furniture> observed = new ArrayList<>(sceneFurniture.values());
			List<Room> rooms = buildRooms(observed, instanceTemplateChunks);
			Map<String, Room> roomBySceneChunk = new LinkedHashMap<>();
			for (Room room : rooms)
			{
				roomBySceneChunk.put(room.sceneKey(), room);
			}
			observed.sort(Comparator
				.comparingInt((Furniture value) -> value.plane)
				.thenComparingInt(value -> value.sceneY)
				.thenComparingInt(value -> value.sceneX)
				.thenComparing(value -> value.name)
				.thenComparingInt(value -> value.objectId));
			List<Map<String, Object>> furniture = new ArrayList<>();
			for (Furniture value : observed)
			{
				Room room = roomBySceneChunk.get(Room.sceneKey(value.plane, value.sceneX / 8, value.sceneY / 8));
				Map<String, Object> mapped = value.toMap(room);
				furniture.add(mapped);
				if (room != null)
				{
					room.furniture.add(mapped);
				}
			}
			List<Map<String, Object>> mappedRooms = new ArrayList<>();
			for (Room room : rooms)
			{
				mappedRooms.add(room.toMap());
			}

			Map<String, Object> inspection = new LinkedHashMap<>();
			inspection.put("schemaVersion", 2);
			inspection.put("loaded", true);
			inspection.put("fromCache", false);
			inspection.put("lastSeenTimestamp", timestamp);
			inspection.put("ownershipEvidence", "building-mode");
			inspection.put("houseLocationId", houseLocation);
			inspection.put("houseStyleId", houseStyle);
			inspection.put("houseSize", houseSize);
			inspection.put("furniture", furniture);
			inspection.put("furnitureCount", furniture.size());
			inspection.put("layoutLoaded", !rooms.isEmpty());
			inspection.put("layoutCoordinateSystem", "exit-portal-relative-room-grid");
			inspection.put("roomCount", mappedRooms.size());
			inspection.put("rooms", mappedRooms);
			inspection.put("exactCoordinatesIncluded", false);
			inspection.put("templateReferencesIncluded", true);
			inspection.put("nearbyPlayersIncluded", false);
			lastInspection = inspection;
			return inspection;
		}

		Map<String, Object> retained = lastInspection;
		if (retained != null)
		{
			Map<String, Object> cached = new LinkedHashMap<>(retained);
			cached.put("fromCache", true);
			return cached;
		}

		Map<String, Object> unavailable = new LinkedHashMap<>();
		unavailable.put("schemaVersion", 2);
		unavailable.put("loaded", false);
		unavailable.put("fromCache", false);
		unavailable.put("lastSeenTimestamp", 0L);
		unavailable.put("ownershipEvidence", "unknown");
		unavailable.put("furniture", new ArrayList<>());
		unavailable.put("furnitureCount", 0);
		unavailable.put("layoutLoaded", false);
		unavailable.put("layoutCoordinateSystem", "exit-portal-relative-room-grid");
		unavailable.put("roomCount", 0);
		unavailable.put("rooms", new ArrayList<>());
		unavailable.put("exactCoordinatesIncluded", false);
		unavailable.put("templateReferencesIncluded", false);
		unavailable.put("nearbyPlayersIncluded", false);
		return unavailable;
	}

	private List<Room> buildRooms(List<Furniture> furniture, int[][][] instanceTemplateChunks)
	{
		Map<String, Room> rooms = new LinkedHashMap<>();
		int anchorChunkX = Math.floorDiv(exitPortalSceneX, 8);
		int anchorChunkY = Math.floorDiv(exitPortalSceneY, 8);
		Room portalRoom = new Room(
			exitPortalPlane,
			anchorChunkX,
			anchorChunkY,
			0,
			0,
			0,
			templateAt(instanceTemplateChunks, exitPortalPlane, anchorChunkX, anchorChunkY)
		);
		rooms.put(portalRoom.sceneKey(), portalRoom);
		for (Furniture value : furniture)
		{
			int chunkX = Math.floorDiv(value.sceneX, 8);
			int chunkY = Math.floorDiv(value.sceneY, 8);
			String sceneKey = Room.sceneKey(value.plane, chunkX, chunkY);
			rooms.computeIfAbsent(sceneKey, ignored -> new Room(
				value.plane,
				chunkX,
				chunkY,
				chunkX - anchorChunkX,
				chunkY - anchorChunkY,
				value.plane - exitPortalPlane,
				templateAt(instanceTemplateChunks, value.plane, chunkX, chunkY)
			));
		}
		List<Room> output = new ArrayList<>(rooms.values());
		output.sort(Comparator
			.comparingInt((Room value) -> value.relativePlane)
			.thenComparingInt(value -> value.relativeY)
			.thenComparingInt(value -> value.relativeX));
		return output.size() > 38 ? new ArrayList<>(output.subList(0, 38)) : output;
	}

	private static int templateAt(int[][][] chunks, int plane, int chunkX, int chunkY)
	{
		if (chunks == null || plane < 0 || plane >= chunks.length || chunks[plane] == null
			|| chunkX < 0 || chunkX >= chunks[plane].length || chunks[plane][chunkX] == null
			|| chunkY < 0 || chunkY >= chunks[plane][chunkX].length)
		{
			return -1;
		}
		return chunks[plane][chunkX][chunkY];
	}

	private static final class Furniture
	{
		private final int objectId;
		private final String name;
		private final List<String> actions;
		private final int sceneX;
		private final int sceneY;
		private final int plane;

		private Furniture(int objectId, String name, List<String> actions, int sceneX, int sceneY, int plane)
		{
			this.objectId = objectId;
			this.name = name;
			this.actions = actions;
			this.sceneX = sceneX;
			this.sceneY = sceneY;
			this.plane = plane;
		}

		private static Furniture from(int objectId, ObjectComposition composition, int sceneX, int sceneY, int plane)
		{
			if (composition == null)
			{
				return null;
			}
			ObjectComposition transformed = composition.getImpostorIds() == null ? composition : composition.getImpostor();
			if (transformed != null)
			{
				composition = transformed;
			}
			return from(objectId, composition.getName(), sceneX, sceneY, plane, composition.getActions());
		}

		private static Furniture from(int objectId, String name, int sceneX, int sceneY, int plane, String[] rawActions)
		{
			if (name == null || name.trim().isEmpty() || "null".equalsIgnoreCase(name))
			{
				return null;
			}
			List<String> actions = new ArrayList<>();
			boolean removable = false;
			if (rawActions != null)
			{
				for (String action : rawActions)
				{
					if (action != null && !action.trim().isEmpty())
					{
						actions.add(action);
						removable |= "remove".equalsIgnoreCase(action);
					}
				}
			}
			return removable ? new Furniture(objectId, name, actions, sceneX, sceneY, plane) : null;
		}

		private Map<String, Object> toMap(Room room)
		{
			Map<String, Object> result = new LinkedHashMap<>();
			result.put("objectId", objectId);
			result.put("name", name);
			result.put("actions", actions);
			result.put("roomId", room == null ? null : room.id());
			result.put("tileX", Math.floorMod(sceneX, 8));
			result.put("tileY", Math.floorMod(sceneY, 8));
			result.put("plane", room == null ? plane : room.relativePlane);
			return result;
		}
	}

	private static final class Room
	{
		private final int plane;
		private final int sceneChunkX;
		private final int sceneChunkY;
		private final int relativeX;
		private final int relativeY;
		private final int relativePlane;
		private final int template;
		private final List<Map<String, Object>> furniture = new ArrayList<>();

		private Room(int plane, int sceneChunkX, int sceneChunkY, int relativeX, int relativeY, int relativePlane, int template)
		{
			this.plane = plane;
			this.sceneChunkX = sceneChunkX;
			this.sceneChunkY = sceneChunkY;
			this.relativeX = relativeX;
			this.relativeY = relativeY;
			this.relativePlane = relativePlane;
			this.template = template;
		}

		private String id()
		{
			return relativePlane + ":" + relativeX + ":" + relativeY;
		}

		private String sceneKey()
		{
			return sceneKey(plane, sceneChunkX, sceneChunkY);
		}

		private static String sceneKey(int plane, int chunkX, int chunkY)
		{
			return plane + ":" + chunkX + ":" + chunkY;
		}

		private Map<String, Object> toMap()
		{
			Map<String, Object> value = new LinkedHashMap<>();
			String roomType = classifiedRoomType();
			value.put("id", id());
			value.put("x", relativeX);
			value.put("y", relativeY);
			value.put("plane", relativePlane);
			value.put("identityKnown", roomType != null);
			value.put("roomType", roomType);
			if (template >= 0)
			{
				int rotation = template >> 1 & 0x3;
				int templateChunkY = template >> 3 & 0x7FF;
				int templateChunkX = template >> 14 & 0x3FF;
				int templatePlane = template >> 24 & 0x3;
				int templateRegionId = (templateChunkX >> 3) << 8 | templateChunkY >> 3;
				int templateChunkIndex = (templateChunkX & 0x7) << 3 | templateChunkY & 0x7;
				value.put("rotation", rotation);
				value.put("templatePlane", templatePlane);
				value.put("templateRegionId", templateRegionId);
				value.put("templateChunkIndex", templateChunkIndex);
			}
			value.put("furniture", furniture);
			value.put("furnitureCount", furniture.size());
			return value;
		}

		private String classifiedRoomType()
		{
			if (hasAny("magic wardrobe", "fancy dress box", "cape rack", "toy box", "armour case"))
			{
				return "Costume room";
			}
			if (hasAny("teleportation focus", "portal frame", "portal nexus") || hasNamedPortal())
			{
				return "Portal chamber";
			}
			if (hasAny("larder", "pump and drain", "firepit with hook", "kitchen sink"))
			{
				return "Kitchen";
			}
			if (hasAny("workbench", "repair bench", "clockmaker's bench", "helmet pluming stand", "tool store"))
			{
				return "Workshop";
			}
			if (hasAny("lectern", "telescope", "globe"))
			{
				return "Study";
			}
			if (hasAny("rejuvenation pool", "restoration pool", "ornate pool", "spirit tree", "fairy ring", "obelisk"))
			{
				return "Superior garden";
			}
			if (hasAny("jewellery box", "boss lair display", "ancient altar", "occult altar", "lunar altar"))
			{
				return "Achievement gallery";
			}
			if (hasAny("boxing mat", "boxing ring", "combat ring", "fencing ring"))
			{
				return "Combat room";
			}
			if (hasAny("attack stone", "balance beam", "prize chest"))
			{
				return "Games room";
			}
			if (hasAny("pet house", "pet feeder", "pet list"))
			{
				return "Menagerie";
			}
			if (hasAny("altar"))
			{
				return "Chapel";
			}
			if (hasAny("bed"))
			{
				return "Bedroom";
			}
			return null;
		}

		private boolean hasNamedPortal()
		{
			for (Map<String, Object> item : furniture)
			{
				String name = String.valueOf(item.get("name")).toLowerCase(java.util.Locale.ROOT);
				if (name.endsWith(" portal") && !"portal".equals(name) && !"exit portal".equals(name))
				{
					return true;
				}
			}
			return false;
		}

		private boolean hasAny(String... fragments)
		{
			for (Map<String, Object> item : furniture)
			{
				String name = String.valueOf(item.get("name")).toLowerCase(java.util.Locale.ROOT);
				for (String fragment : fragments)
				{
					if (name.contains(fragment))
					{
						return true;
					}
				}
			}
			return false;
		}
	}
}

package org.gielinor.profilesync;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.Collections;
import java.util.Map;
import net.runelite.client.util.Filepath;

final class ProfileExportStore
{
	private final Gson gson;
	private final Filepath directory;

	ProfileExportStore(Gson gson, Filepath directory)
	{
		this.gson = gson.newBuilder().serializeNulls().setPrettyPrinting().create();
		this.directory = directory;
	}

	Map<String, Object> readLatest()
	{
		return read(directory.join("latest.json"));
	}

	Map<String, Object> readAccount(String rsn)
	{
		return read(directory.join(safeFileName(rsn) + ".json"));
	}

	@SuppressWarnings("unchecked")
	private Map<String, Object> read(Filepath latest)
	{
		if (!latest.isFile())
		{
			return Collections.emptyMap();
		}

		try (Reader reader = latest.openBufferedReader())
		{
			Map<String, Object> parsed = gson.fromJson(reader, Map.class);
			return parsed != null ? parsed : Collections.emptyMap();
		}
		catch (IOException | RuntimeException e)
		{
			return Collections.emptyMap();
		}
	}

	void write(String rsn, Map<String, Object> snapshot) throws IOException
	{
		directory.createDirectories();
		String json = gson.toJson(snapshot) + System.lineSeparator();
		writeAtomically(directory.join("latest.json"), json);
		writeAtomically(directory.join(safeFileName(rsn) + ".json"), json);
	}

	private void writeAtomically(Filepath destination, String json) throws IOException
	{
		Filepath temporary = directory.join(destination.getFileName() + ".tmp");
		temporary.write(json);
		try
		{
			temporary.moveTo(destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (AtomicMoveNotSupportedException e)
		{
			temporary.moveTo(destination, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	static String safeFileName(String rsn)
	{
		String safe = rsn == null ? "" : rsn.replaceAll("[^a-zA-Z0-9 _-]+", "_").trim();
		safe = safe.replaceAll("^[ _.]+|[ _.]+$", "");
		if (safe.isEmpty())
		{
			return "player";
		}
		if (safe.matches("(?i)CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9]"))
		{
			return "_" + safe;
		}
		return safe;
	}
}

package org.gielinor.profilesync;

import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/** Reads only the server-backed assignment state RuneLite uses for its Slayer counter. */
final class SlayerTaskSnapshot
{
	private static final int BOSS_TASK_ID = 98;
	private static final int KRYSTILIA_SLAYER_MASTER = 7;
	private static final int MAX_GAME_LABEL_LENGTH = 120;

	interface Source
	{
		int varp(int id);
		int varbit(int id);
		List<Integer> rowsByValue(int tableId, int columnId, int tupleIndex, Object value);
		Object[] field(int rowId, int columnId, int tupleIndex);
	}

	private SlayerTaskSnapshot()
	{
	}

	static Map<String, Object> build(Client client, long observedAt)
	{
		return build(new Source()
		{
			@Override
			public int varp(int id)
			{
				return client.getVarpValue(id);
			}

			@Override
			public int varbit(int id)
			{
				return client.getVarbitValue(id);
			}

			@Override
			public List<Integer> rowsByValue(int tableId, int columnId, int tupleIndex, Object value)
			{
				return client.getDBRowsByValue(tableId, columnId, tupleIndex, value);
			}

			@Override
			public Object[] field(int rowId, int columnId, int tupleIndex)
			{
				return client.getDBTableField(rowId, columnId, tupleIndex);
			}
		}, observedAt);
	}

	static Map<String, Object> build(Source source, long observedAt)
	{
		Map<String, Object> result = base(false, observedAt);
		try
		{
			int remaining = source.varp(VarPlayerID.SLAYER_COUNT);
			int original = source.varp(VarPlayerID.SLAYER_COUNT_ORIGINAL);
			int taskId = source.varp(VarPlayerID.SLAYER_TARGET);
			int areaId = source.varp(VarPlayerID.SLAYER_AREA);
			int masterId = source.varbit(VarbitID.SLAYER_MASTER);

			result = base(true, observedAt);
			result.put("status", remaining > 0 ? "live" : "none");
			result.put("points", nonNegative(source.varbit(VarbitID.SLAYER_POINTS)));
			result.put("streak", nonNegative(source.varbit(
				masterId == KRYSTILIA_SLAYER_MASTER
					? VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED
					: VarbitID.SLAYER_TASKS_COMPLETED)));

			if (remaining <= 0)
			{
				result.put("task", null);
				return result;
			}

			Map<String, Object> task = new LinkedHashMap<>();
			task.put("taskId", nonNegative(taskId));
			task.put("remaining", nonNegative(remaining));
			task.put("original", original > 0 ? original : null);
			task.put("assignedById", nonNegative(masterId));
			task.put("requiredLocationId", areaId > 0 ? areaId : null);

			Integer taskRow = resolveTaskRow(source, taskId);
			task.put("monster", taskRow == null
				? null
				: safeLabel(first(source.field(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0))));
			task.put("requiredLocation", resolveArea(source, areaId));
			task.put("identityKnown", task.get("monster") != null);
			result.put("task", task);
			return result;
		}
		catch (RuntimeException exception)
		{
			result.put("status", "unavailable");
			result.put("task", null);
			return result;
		}
	}

	private static Map<String, Object> base(boolean loaded, long observedAt)
	{
		Map<String, Object> result = new LinkedHashMap<>();
		result.put("schemaVersion", 1);
		result.put("source", "RuneLite server-backed Slayer assignment variables");
		result.put("sourceVersion", "runelite-1.13.6-task-vars");
		result.put("taskLoaded", loaded);
		result.put("taskFromCache", false);
		result.put("taskLastSeenTimestamp", loaded && observedAt > 0
			? Instant.ofEpochMilli(observedAt).toString()
			: null);
		result.put("status", loaded ? "none" : "unavailable");
		result.put("points", null);
		result.put("streak", null);
		result.put("task", null);
		return result;
	}

	private static Integer resolveTaskRow(Source source, int taskId)
	{
		if (taskId == BOSS_TASK_ID)
		{
			List<Integer> rows = source.rowsByValue(
				DBTableID.SlayerTaskSublist.ID,
				DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
				0,
				source.varbit(VarbitID.SLAYER_TARGET_BOSSID));
			if (rows == null || rows.isEmpty())
			{
				return null;
			}
			Object value = first(source.field(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0));
			return value instanceof Integer ? (Integer) value : null;
		}

		List<Integer> rows = source.rowsByValue(
			DBTableID.SlayerTask.ID,
			DBTableID.SlayerTask.COL_ID,
			0,
			taskId);
		return rows == null || rows.isEmpty() ? null : rows.get(0);
	}

	private static String resolveArea(Source source, int areaId)
	{
		if (areaId <= 0)
		{
			return null;
		}
		List<Integer> rows = source.rowsByValue(
			DBTableID.SlayerArea.ID,
			DBTableID.SlayerArea.COL_AREA_ID,
			0,
			areaId);
		if (rows == null || rows.isEmpty())
		{
			return null;
		}
		return safeLabel(first(source.field(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0)));
	}

	private static Object first(Object[] values)
	{
		return values == null || values.length == 0 ? null : values[0];
	}

	private static Integer nonNegative(int value)
	{
		return value >= 0 ? value : null;
	}

	private static String safeLabel(Object value)
	{
		if (!(value instanceof String))
		{
			return null;
		}
		String normalized = ((String) value)
			.replaceAll("<[^>]*>", "")
			.replaceAll("[\\p{Cntrl}<>]", "")
			.replaceAll("\\s+", " ")
			.trim();
		if (normalized.isEmpty())
		{
			return null;
		}
		return normalized.length() <= MAX_GAME_LABEL_LENGTH
			? normalized
			: normalized.substring(0, MAX_GAME_LABEL_LENGTH);
	}
}

package org.gielinor.profilesync;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class AchievementDiarySnapshotTest
{
	private static final List<String> REGION_KEYS = Arrays.asList(
		"ardougne", "desert", "falador", "fremennik", "kandarin", "karamja",
		"kourend_kebos", "lumbridge_draynor", "morytania", "varrock",
		"western_provinces", "wilderness"
	);

	@Test
	@SuppressWarnings("unchecked")
	public void exportsAllTwelveRegionsAndTheVerifiedCatalogueTotals()
	{
		Map<String, Object> snapshot = AchievementDiarySnapshot.build(varbitId -> 0);
		Map<String, Object> regions = (Map<String, Object>) snapshot.get("regions");

		assertEquals(2, snapshot.get("schemaVersion"));
		assertEquals("runelite-1.13.6-varbits", snapshot.get("sourceVersion"));
		assertEquals(REGION_KEYS, Arrays.asList(regions.keySet().toArray(new String[0])));
		assertEquals(48, snapshot.get("totalTierCount"));
		assertEquals(0, snapshot.get("completedTierCount"));
		assertEquals(false, snapshot.get("allComplete"));

		Map<String, int[]> expectedTotals = new LinkedHashMap<>();
		expectedTotals.put("ardougne", new int[]{10, 12, 12, 8});
		expectedTotals.put("desert", new int[]{11, 12, 10, 6});
		expectedTotals.put("falador", new int[]{11, 14, 11, 6});
		expectedTotals.put("fremennik", new int[]{10, 9, 9, 6});
		expectedTotals.put("kandarin", new int[]{11, 14, 11, 7});
		expectedTotals.put("karamja", new int[]{10, 19, 10, 5});
		expectedTotals.put("kourend_kebos", new int[]{12, 13, 10, 8});
		expectedTotals.put("lumbridge_draynor", new int[]{12, 12, 11, 6});
		expectedTotals.put("morytania", new int[]{11, 11, 10, 6});
		expectedTotals.put("varrock", new int[]{14, 13, 10, 5});
		expectedTotals.put("western_provinces", new int[]{11, 13, 13, 7});
		expectedTotals.put("wilderness", new int[]{12, 11, 10, 7});

		int taskTotal = 0;
		for (Map.Entry<String, Object> regionEntry : regions.entrySet())
		{
			Map<String, Object> region = (Map<String, Object>) regionEntry.getValue();
			int[] actualTotals = new int[4];
			int tierIndex = 0;
			for (String tierName : Arrays.asList("easy", "medium", "hard", "elite"))
			{
				Map<String, Object> tier = (Map<String, Object>) region.get(tierName);
				actualTotals[tierIndex++] = (Integer) tier.get("totalTaskCount");
				taskTotal += (Integer) tier.get("totalTaskCount");
				assertEquals("available", tier.get("signalStatus"));
			}
			assertArrayEquals(expectedTotals.get(regionEntry.getKey()), actualTotals);
		}
		assertEquals(492, taskTotal);
	}

	@Test
	public void exportsPartialTaskProgressWithoutClaimingCompletion()
	{
		Map<Integer, Integer> signals = signals(
			VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, 0,
			VarbitID.ARDOUGNE_EASY_COUNT, 3,
			VarbitID.ARDOUGNE_EASY_REWARD, 0);
		Map<String, Object> tier = tier(AchievementDiarySnapshot.build(id -> signals.getOrDefault(id, 0)), "ardougne", "easy");

		assertEquals(false, tier.get("tierComplete"));
		assertEquals(false, tier.get("rewardClaimed"));
		assertEquals(3, tier.get("completedTaskCount"));
		assertEquals(10, tier.get("totalTaskCount"));
	}

	@Test
	public void completionSignalWinsOverAStaleCountWithoutClaimingTheReward()
	{
		Map<Integer, Integer> signals = signals(
			VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, 1,
			VarbitID.ARDOUGNE_EASY_COUNT, 4,
			VarbitID.ARDOUGNE_EASY_REWARD, 0);
		Map<String, Object> tier = tier(AchievementDiarySnapshot.build(id -> signals.getOrDefault(id, 0)), "ardougne", "easy");

		assertEquals(true, tier.get("complete"));
		assertEquals(true, tier.get("tierComplete"));
		assertEquals(false, tier.get("rewardClaimed"));
		assertEquals(10, tier.get("completedTaskCount"));
	}

	@Test
	public void claimedRewardIsMonotonicPositiveCompletionEvidence()
	{
		Map<Integer, Integer> signals = signals(
			VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, 0,
			VarbitID.ARDOUGNE_EASY_COUNT, 2,
			VarbitID.ARDOUGNE_EASY_REWARD, 1);
		Map<String, Object> tier = tier(AchievementDiarySnapshot.build(id -> signals.getOrDefault(id, 0)), "ardougne", "easy");

		assertEquals(true, tier.get("tierComplete"));
		assertEquals(true, tier.get("rewardClaimed"));
		assertEquals(10, tier.get("completedTaskCount"));
		assertEquals(1, tier.get("value"));
	}

	@Test
	public void zeroSignalsAreKnownZeroRatherThanUnavailable()
	{
		Map<String, Object> tier = tier(AchievementDiarySnapshot.build(id -> 0), "desert", "easy");

		assertEquals(false, tier.get("tierComplete"));
		assertEquals(false, tier.get("rewardClaimed"));
		assertEquals(0, tier.get("completedTaskCount"));
		assertEquals("available", tier.get("signalStatus"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void unavailableSignalsRemainExplicitlyUnknownAtEveryAggregate()
	{
		Map<String, Object> snapshot = AchievementDiarySnapshot.build(id -> null);
		Map<String, Object> tier = tier(snapshot, "morytania", "medium");
		Map<String, Object> regions = (Map<String, Object>) snapshot.get("regions");
		Map<String, Object> morytania = (Map<String, Object>) regions.get("morytania");

		assertNull(tier.get("complete"));
		assertNull(tier.get("value"));
		assertNull(tier.get("rewardClaimed"));
		assertNull(tier.get("tierComplete"));
		assertNull(tier.get("completedTaskCount"));
		assertEquals(11, tier.get("totalTaskCount"));
		assertEquals("unavailable", tier.get("signalStatus"));
		assertNull(morytania.get("completedTierCount"));
		assertNull(morytania.get("allComplete"));
		assertNull(snapshot.get("completedTierCount"));
		assertNull(snapshot.get("completionPercent"));
		assertNull(snapshot.get("allComplete"));
	}

	@Test
	public void partialSignalAvailabilityDoesNotFabricateTheMissingFields()
	{
		Map<String, Object> tier = tier(AchievementDiarySnapshot.build(id ->
			id == VarbitID.FALADOR_MED_COUNT ? 5 : null), "falador", "medium");

		assertEquals(false, tier.get("tierComplete"));
		assertNull(tier.get("rewardClaimed"));
		assertEquals(5, tier.get("completedTaskCount"));
		assertEquals("partial", tier.get("signalStatus"));
	}

	@Test
	public void mapsKaramjasAtjunSignalsSeparatelyFromItsCountSignals()
	{
		Map<Integer, Integer> signals = signals(
			VarbitID.ATJUN_MED_DONE, 1,
			VarbitID.KARAMJA_MED_COUNT, 19,
			VarbitID.ATJUN_MED_REWARD, 0);
		Map<String, Object> tier = tier(AchievementDiarySnapshot.build(id -> signals.getOrDefault(id, 0)), "karamja", "medium");

		assertEquals(true, tier.get("tierComplete"));
		assertEquals(false, tier.get("rewardClaimed"));
		assertEquals(19, tier.get("completedTaskCount"));
		assertEquals(19, tier.get("totalTaskCount"));
	}

	@Test
	public void rejectsOutOfRangeCountsInsteadOfClampingThem()
	{
		Map<Integer, Integer> signals = signals(
			VarbitID.VARROCK_DIARY_ELITE_COMPLETE, 0,
			VarbitID.VARROCK_ELITE_COUNT, 99,
			VarbitID.VARROCK_ELITE_REWARD, 0);
		Map<String, Object> tier = tier(AchievementDiarySnapshot.build(
			id -> signals.containsKey(id) ? signals.get(id) : null), "varrock", "elite");

		assertEquals(false, tier.get("tierComplete"));
		assertNull(tier.get("completedTaskCount"));
		assertEquals("partial", tier.get("signalStatus"));
	}

	@SuppressWarnings("unchecked")
	private static Map<String, Object> tier(Map<String, Object> snapshot, String regionName, String tierName)
	{
		Map<String, Object> regions = (Map<String, Object>) snapshot.get("regions");
		Map<String, Object> region = (Map<String, Object>) regions.get(regionName);
		return (Map<String, Object>) region.get(tierName);
	}

	private static Map<Integer, Integer> signals(int... values)
	{
		Map<Integer, Integer> signals = new LinkedHashMap<>();
		for (int index = 0; index < values.length; index += 2)
		{
			signals.put(values[index], values[index + 1]);
		}
		return signals;
	}
}

package org.gielinor.profilesync;

import java.util.Collections;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CollectionLogAccountSnapshotsTest
{
	@Test
	@SuppressWarnings("unchecked")
	public void preservesIndependentObservationsAcrossAccountRoundTrip()
	{
		CollectionLogAccountSnapshots accounts = new CollectionLogAccountSnapshots();
		accounts.activate("Sailor A").observePage("Abyssal Sire", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(13262, "Abyssal orphan", true, 1)
		), 1_000L);
		accounts.activate("Sailor B").observePage("Barrows Chests", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(4708, "Ahrim's hood", false, 0)
		), 2_000L);

		Map<String, Object> restoredA = accounts.activate("sailor a").toMap();
		Map<String, Object> pagesA = (Map<String, Object>) restoredA.get("pages");
		assertTrue(pagesA.containsKey("abyssal-sire"));
		assertFalse(pagesA.containsKey("barrows-chests"));

		Map<String, Object> restoredB = accounts.activate("SAILOR B").toMap();
		Map<String, Object> pagesB = (Map<String, Object>) restoredB.get("pages");
		assertTrue(pagesB.containsKey("barrows-chests"));
		assertFalse(pagesB.containsKey("abyssal-sire"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void exportMergeRetainsStoredPagesAndNewerCurrentState()
	{
		CollectionLogSnapshot stored = new CollectionLogSnapshot();
		stored.observePage("Abyssal Sire", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(13262, "Abyssal orphan", true, 1)
		), 1_000L);
		CollectionLogSnapshot current = new CollectionLogSnapshot();
		current.observePage("Barrows Chests", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(4708, "Ahrim's hood", false, 0)
		), 2_000L);

		Map<String, Object> merged = (Map<String, Object>) CollectionLogAccountSnapshots.mergeForExport(stored.toMap(), current.toMap());
		Map<String, Object> pages = (Map<String, Object>) merged.get("pages");
		assertEquals(2, pages.size());
		assertTrue(pages.containsKey("abyssal-sire"));
		assertTrue(pages.containsKey("barrows-chests"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void activatingObservationAccountBeforeFirstTickCannotLeakPreviousAccount()
	{
		CollectionLogAccountSnapshots accounts = new CollectionLogAccountSnapshots();
		accounts.activate("Sailor A").observePage("Abyssal Sire", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(13262, "Abyssal orphan", true, 1)
		), 1_000L);

		accounts.activate("Sailor B").observePage("Barrows Chests", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(4708, "Ahrim's hood", true, 1)
		), 2_000L);

		Map<String, Object> pagesA = (Map<String, Object>) accounts.activate("Sailor A").toMap().get("pages");
		Map<String, Object> pagesB = (Map<String, Object>) accounts.activate("Sailor B").toMap().get("pages");
		assertTrue(pagesA.containsKey("abyssal-sire"));
		assertFalse(pagesA.containsKey("barrows-chests"));
		assertTrue(pagesB.containsKey("barrows-chests"));
		assertFalse(pagesB.containsKey("abyssal-sire"));
	}
}

package org.gielinor.profilesync;

import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CollectionLogSnapshotTest
{
	@Test
	@SuppressWarnings("unchecked")
	public void recordsOnlyExplicitlyObservedPageSlots()
	{
		CollectionLogSnapshot snapshot = new CollectionLogSnapshot();
		long observedAt = Instant.parse("2026-08-20T12:30:00Z").toEpochMilli();
		assertTrue(snapshot.observePage("Bosses", "Abyssal Sire", Arrays.asList(
			new CollectionLogSnapshot.ItemObservation(13262, "Abyssal orphan", true, 1),
			new CollectionLogSnapshot.ItemObservation(7979, "Abyssal head", false, 0)
		), observedAt));

		Map<String, Object> exported = snapshot.toMap();
		assertEquals("partial", exported.get("status"));
		assertEquals("observed-pages-only", exported.get("coverage"));
		assertEquals(1, exported.get("observedPageCount"));
		assertEquals(2, exported.get("observedSlotCount"));
		assertEquals(1, exported.get("obtainedObservedSlotCount"));

		Map<String, Object> pages = (Map<String, Object>) exported.get("pages");
		Map<String, Object> page = (Map<String, Object>) pages.get("abyssal-sire");
		assertEquals("Bosses", page.get("category"));
		assertEquals("2026-08-20T12:30:00Z", page.get("observedAt"));
		assertEquals(1, page.get("obtainedSlotCount"));
		assertEquals(1, page.get("missingSlotCount"));
		Map<String, Object> entries = (Map<String, Object>) page.get("entries");
		assertEquals(true, ((Map<String, Object>) entries.get("13262")).get("obtained"));
		assertEquals(false, ((Map<String, Object>) entries.get("7979")).get("obtained"));
		assertFalse(pages.containsKey("unvisited-page"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void newerPageObservationReplacesOlderState()
	{
		CollectionLogSnapshot snapshot = new CollectionLogSnapshot();
		snapshot.observePage("Abyssal Sire", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(7979, "Abyssal head", false, 0)
		), 1_000L);
		snapshot.observePage("Abyssal Sire", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(7979, "Abyssal head", true, 2)
		), 2_000L);
		snapshot.observePage("Abyssal Sire", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(7979, "Abyssal head", false, 0)
		), 1_500L);

		Map<String, Object> pages = (Map<String, Object>) snapshot.toMap().get("pages");
		Map<String, Object> page = (Map<String, Object>) pages.get("abyssal-sire");
		Map<String, Object> entries = (Map<String, Object>) page.get("entries");
		Map<String, Object> item = (Map<String, Object>) entries.get("7979");
		assertEquals(true, item.get("obtained"));
		assertEquals(2, item.get("quantity"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void refusesTransientProgressRegression()
	{
		CollectionLogSnapshot snapshot = new CollectionLogSnapshot();
		snapshot.observePage("Bosses", "Abyssal Sire", Arrays.asList(
			new CollectionLogSnapshot.ItemObservation(13262, "Abyssal orphan", true, 1),
			new CollectionLogSnapshot.ItemObservation(7979, "Abyssal head", false, 0)
		), 1_000L);
		assertFalse(snapshot.observePage("Bosses", "Abyssal Sire", Arrays.asList(
			new CollectionLogSnapshot.ItemObservation(13262, "Abyssal orphan", false, 0),
			new CollectionLogSnapshot.ItemObservation(7979, "Abyssal head", false, 0)
		), 2_000L));

		Map<String, Object> pages = (Map<String, Object>) snapshot.toMap().get("pages");
		Map<String, Object> page = (Map<String, Object>) pages.get("abyssal-sire");
		assertEquals(1, page.get("obtainedSlotCount"));
	}

	@Test
	public void recordsAuthoritativeUniqueCountsSeparatelyFromObservedSlots()
	{
		CollectionLogSnapshot snapshot = new CollectionLogSnapshot();
		snapshot.observeUniqueCounts(425, 1_699, Instant.parse("2026-08-20T12:30:00Z").toEpochMilli());
		Map<String, Object> exported = snapshot.toMap();
		assertEquals(425, exported.get("uniqueObtainedCount"));
		assertEquals(1_699, exported.get("uniqueItemCount"));
		assertEquals("2026-08-20T12:30:00Z", exported.get("uniqueCountsObservedAt"));
	}

	@Test
	public void roundTripsStoredObservationsAndKeepsUnknownWhenEmpty()
	{
		CollectionLogSnapshot empty = new CollectionLogSnapshot();
		assertEquals("unavailable", empty.toMap().get("status"));
		assertEquals(0, empty.toMap().get("observedPageCount"));

		CollectionLogSnapshot original = new CollectionLogSnapshot();
		original.observePage("Barrows Chests", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(4708, "Ahrim's hood", true, 3)
		), Instant.parse("2026-08-20T12:30:00Z").toEpochMilli());
		CollectionLogSnapshot restored = new CollectionLogSnapshot();
		restored.restore(original.toMap());
		assertEquals(original.toMap(), restored.toMap());
	}

	@Test
	public void rejectsPagesWithoutValidSlots()
	{
		CollectionLogSnapshot snapshot = new CollectionLogSnapshot();
		assertFalse(snapshot.observePage("", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(1, "Item", true, 1)
		), 1L));
		assertFalse(snapshot.observePage("Overview", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(-1, "", false, 0)
		), 1L));
		assertEquals(0, snapshot.toMap().get("observedPageCount"));
	}

	@Test
	public void rejectsObservationsWithoutRealTimestamps()
	{
		CollectionLogSnapshot snapshot = new CollectionLogSnapshot();
		assertFalse(snapshot.observePage("Overview", Collections.singletonList(
			new CollectionLogSnapshot.ItemObservation(1, "Item", true, 1)
		), 0L));
		snapshot.observeUniqueCounts(1, 10, 0L);
		assertEquals(0, snapshot.toMap().get("observedPageCount"));
		assertFalse(snapshot.toMap().containsKey("uniqueCountsObservedAt"));
	}
}

