package org.gielinor.profilesync;

import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;

public class PlayerModelSnapshotTest
{
	@Test
	public void encodesCompactImmutableMeshArrays()
	{
		float[] x = {1.2f, -2.8f, 3.5f};
		Map<String, Object> model = PlayerModelSnapshot.encode(
			3,
			x,
			new float[]{4, 5, 6},
			new float[]{7, 8, 9},
			1,
			new int[]{0},
			new int[]{1},
			new int[]{2},
			new int[]{100},
			new int[]{101},
			new int[]{102},
			new byte[]{(byte) 200},
			new short[]{-1});

		assertEquals(1, model.get("schemaVersion"));
		assertEquals(3, model.get("vertexCount"));
		assertEquals(1, model.get("faceCount"));
		assertArrayEquals(new int[]{1, -3, 4}, (int[]) model.get("verticesX"));
		assertArrayEquals(new int[]{200}, (int[]) model.get("transparencies"));
		assertArrayEquals(new int[]{-1}, (int[]) model.get("textures"));

		x[0] = 99;
		assertArrayEquals(new int[]{1, -3, 4}, (int[]) model.get("verticesX"));
	}

	@Test
	public void omitsOptionalChannelsAndRejectsIncompleteGeometry()
	{
		Map<String, Object> model = PlayerModelSnapshot.encode(
			3,
			new float[]{1, 2, 3},
			new float[]{1, 2, 3},
			new float[]{1, 2, 3},
			1,
			new int[]{0},
			new int[]{1},
			new int[]{2},
			new int[]{100},
			new int[]{100},
			new int[]{-1},
			null,
			null);

		assertFalse(model.containsKey("transparencies"));
		assertFalse(model.containsKey("textures"));
		assertNull(PlayerModelSnapshot.encode(
			3,
			new float[]{1, 2},
			new float[]{1, 2, 3},
			new float[]{1, 2, 3},
			1,
			new int[]{0},
			new int[]{1},
			new int[]{2},
			new int[]{100},
			new int[]{100},
			new int[]{100},
			null,
			null));
	}
}

package org.gielinor.profilesync;

import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ObjectID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PohSnapshotTrackerTest
{
	@Test
	public void requiresOwnHouseBuildingModeBeforeClaimingFurniture()
	{
		PohSnapshotTracker tracker = new PohSnapshotTracker();
		tracker.observeForTest(new Object(), ObjectID.POH_EXIT_PORTAL, "Portal", "Enter");
		tracker.observeForTest(new Object(), 1001, "Oak larder", "Search", "Remove");

		Map<String, Object> visitorView = tracker.snapshot(100L, false, 3, 2, 5, null);
		assertFalse((Boolean) visitorView.get("loaded"));

		Map<String, Object> ownHouse = tracker.snapshot(200L, true, 3, 2, 5, null);
		assertTrue((Boolean) ownHouse.get("loaded"));
		assertFalse((Boolean) ownHouse.get("fromCache"));
		assertEquals("building-mode", ownHouse.get("ownershipEvidence"));
		assertEquals(1, ownHouse.get("furnitureCount"));
		assertEquals("Oak larder", furniture(ownHouse).get(0).get("name"));
		assertFalse(ownHouse.containsKey("coordinates"));
	}

	@Test
	public void retainsTheLastInspectionWithoutTurningUnknownObjectsIntoAbsence()
	{
		PohSnapshotTracker tracker = new PohSnapshotTracker();
		tracker.observeForTest(new Object(), ObjectID.POH_EXIT_PORTAL, "Portal", "Enter");
		tracker.observeForTest(new Object(), 1002, "Fancy rejuvenation pool", "Drink", "Remove");
		tracker.observeForTest(new Object(), 1003, "Wall", "Examine");
		tracker.snapshot(300L, true, 1, 4, 7, null);
		tracker.clearScene();

		Map<String, Object> cached = tracker.snapshot(400L, false, 0, 0, 0, null);
		assertTrue((Boolean) cached.get("loaded"));
		assertTrue((Boolean) cached.get("fromCache"));
		assertEquals(300L, cached.get("lastSeenTimestamp"));
		assertEquals(1, cached.get("furnitureCount"));
	}

	@Test
	public void restoresTheLastInspectionAcrossPluginRestarts()
	{
		PohSnapshotTracker original = new PohSnapshotTracker();
		original.observeForTest(new Object(), ObjectID.POH_EXIT_PORTAL, "Portal", "Enter");
		original.observeForTest(new Object(), 1004, "Basic jewellery box", "Teleport", "Remove");
		Map<String, Object> inspection = original.snapshot(500L, true, 2, 1, 4, null);

		PohSnapshotTracker restarted = new PohSnapshotTracker();
		restarted.restore(inspection);
		Map<String, Object> cached = restarted.snapshot(600L, false, 0, 0, 0, null);
		assertTrue((Boolean) cached.get("loaded"));
		assertTrue((Boolean) cached.get("fromCache"));
		assertEquals(500L, cached.get("lastSeenTimestamp"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void exportsPortalRelativeRoomsAndFurnitureTilesWithoutWorldCoordinates()
	{
		PohSnapshotTracker tracker = new PohSnapshotTracker();
		tracker.observeForTest(new Object(), ObjectID.POH_EXIT_PORTAL, "Portal", 40, 40, 0, "Enter");
		tracker.observeForTest(new Object(), 1005, "Oak larder", 49, 43, 0, "Search", "Remove");
		int[][][] chunks = emptyChunks();
		chunks[0][5][5] = packedChunk(0, 400, 500, 1);
		chunks[0][6][5] = packedChunk(0, 401, 500, 2);

		Map<String, Object> inspection = tracker.snapshot(700L, true, 3, 2, 5, chunks);
		List<Map<String, Object>> rooms = (List<Map<String, Object>>) inspection.get("rooms");
		List<Map<String, Object>> furniture = furniture(inspection);

		assertEquals(2, inspection.get("schemaVersion"));
		assertEquals(true, inspection.get("layoutLoaded"));
		assertEquals(2, rooms.size());
		assertEquals("0:0:0", rooms.get(0).get("id"));
		assertEquals("0:1:0", rooms.get(1).get("id"));
		assertEquals("0:1:0", furniture.get(0).get("roomId"));
		assertEquals(1, furniture.get(0).get("tileX"));
		assertEquals(3, furniture.get(0).get("tileY"));
		assertFalse(inspection.containsKey("coordinates"));
		assertEquals(false, inspection.get("exactCoordinatesIncluded"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void ignoresUnoccupiedInstanceChunksAndLabelsHighConfidenceRooms()
	{
		PohSnapshotTracker tracker = new PohSnapshotTracker();
		tracker.observeForTest(new Object(), ObjectID.POH_EXIT_PORTAL, "Portal", 40, 40, 0, "Enter");
		tracker.observeForTest(new Object(), 1006, "Oak larder", 49, 43, 0, "Search", "Remove");
		tracker.observeForTest(new Object(), 1007, "Teak cape rack", 57, 43, 0, "Search", "Remove");
		int[][][] chunks = emptyChunks();
		for (int x = 0; x < 13; x++)
		{
			for (int y = 0; y < 8; y++)
			{
				chunks[0][x][y] = packedChunk(0, 400 + x, 500 + y, 0);
			}
		}

		Map<String, Object> inspection = tracker.snapshot(800L, true, 3, 2, 5, chunks);
		List<Map<String, Object>> rooms = (List<Map<String, Object>>) inspection.get("rooms");

		assertEquals(3, rooms.size());
		assertEquals(3, inspection.get("roomCount"));
		assertEquals("Kitchen", rooms.get(1).get("roomType"));
		assertEquals(true, rooms.get(1).get("identityKnown"));
		assertEquals("Costume room", rooms.get(2).get("roomType"));
	}

	private static int[][][] emptyChunks()
	{
		int[][][] chunks = new int[4][13][13];
		for (int plane = 0; plane < chunks.length; plane++)
		{
			for (int x = 0; x < chunks[plane].length; x++)
			{
				java.util.Arrays.fill(chunks[plane][x], -1);
			}
		}
		return chunks;
	}

	private static int packedChunk(int plane, int chunkX, int chunkY, int rotation)
	{
		return plane << 24 | chunkX << 14 | chunkY << 3 | rotation << 1;
	}

	@SuppressWarnings("unchecked")
	private static List<Map<String, Object>> furniture(Map<String, Object> snapshot)
	{
		return (List<Map<String, Object>>) snapshot.get("furniture");
	}
}

package org.gielinor.profilesync;

import com.google.gson.Gson;
import java.nio.file.Files;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ProfileExportStoreTest
{
	@Rule
	public TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void writesLatestAndAccountSnapshot() throws Exception
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporaryFolder.getRoot().toPath());
		ProfileExportStore store = new ProfileExportStore(new Gson(), directory);
		Map<String, Object> snapshot = new LinkedHashMap<>();
		snapshot.put("schemaVersion", 1);
		snapshot.put("rsn", "Chew/4L");

		store.write("Chew/4L", snapshot);

		assertTrue(Files.isRegularFile(temporaryFolder.getRoot().toPath().resolve("latest.json")));
		assertTrue(Files.isRegularFile(temporaryFolder.getRoot().toPath().resolve("Chew_4L.json")));
		assertEquals("Chew/4L", store.readLatest().get("rsn"));
	}

	@Test
	public void replacesExistingSnapshotsAndPreservesUtf8() throws Exception
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporaryFolder.getRoot().toPath()).join("exports");
		ProfileExportStore store = new ProfileExportStore(new Gson(), directory);
		Map<String, Object> snapshot = new LinkedHashMap<>();
		snapshot.put("rsn", "Player");
		store.write("Player", snapshot);

		snapshot.put("note", "Caf\u00e9");
		store.write("Player", snapshot);

		assertEquals("Caf\u00e9", store.readLatest().get("note"));
		assertEquals(Files.readString(temporaryFolder.getRoot().toPath().resolve("exports/latest.json")),
			Files.readString(temporaryFolder.getRoot().toPath().resolve("exports/Player.json")));
		assertFalse(directory.join("latest.json.tmp").exists());
		assertFalse(directory.join("Player.json.tmp").exists());
	}

	@Test
	public void missingOrInvalidSnapshotsReturnAnEmptyMap() throws Exception
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporaryFolder.getRoot().toPath());
		ProfileExportStore store = new ProfileExportStore(new Gson(), directory);
		assertTrue(store.readLatest().isEmpty());

		directory.join("latest.json").write("not json");
		assertTrue(store.readLatest().isEmpty());
	}

	@Test
	public void fallsBackToPlayerForUnsafeEmptyName()
	{
		assertEquals("player", ProfileExportStore.safeFileName("***"));
		assertEquals("player", ProfileExportStore.safeFileName(null));
		assertEquals("_CON", ProfileExportStore.safeFileName("CON"));
	}

	@Test
	public void readsEachAccountSnapshotInsteadOfOnlyLatest() throws Exception
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporaryFolder.getRoot().toPath());
		ProfileExportStore store = new ProfileExportStore(new Gson(), directory);
		store.write("Sailor A", Map.of("rsn", "Sailor A"));
		store.write("Sailor B", Map.of("rsn", "Sailor B"));

		assertEquals("Sailor B", store.readLatest().get("rsn"));
		assertEquals("Sailor A", store.readAccount("Sailor A").get("rsn"));
		assertEquals("Sailor B", store.readAccount("Sailor B").get("rsn"));
		assertTrue(store.readAccount("Unseen account").isEmpty());
	}

	@Test
	public void preservesExplicitUnknownSignals() throws Exception
	{
		Filepath directory = Filepath.Unchecked.getRooted(temporaryFolder.getRoot().toPath());
		ProfileExportStore store = new ProfileExportStore(new Gson(), directory);
		Map<String, Object> snapshot = new LinkedHashMap<>();
		snapshot.put("uniqueItemCount", null);
		store.write("Player", snapshot);

		Map<String, Object> restored = store.readAccount("Player");
		assertTrue(restored.containsKey("uniqueItemCount"));
		assertEquals(null, restored.get("uniqueItemCount"));
	}
}

package org.gielinor.profilesync;

import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;

public class SlayerTaskSnapshotTest
{
	private static final long OBSERVED_AT = 1_786_089_600_000L;

	@Test
	@SuppressWarnings("unchecked")
	public void exportsAProvableLocationBoundAssignment()
	{
		FakeSource source = new FakeSource();
		source.varps.put(VarPlayerID.SLAYER_COUNT, 87);
		source.varps.put(VarPlayerID.SLAYER_COUNT_ORIGINAL, 143);
		source.varps.put(VarPlayerID.SLAYER_TARGET, 42);
		source.varps.put(VarPlayerID.SLAYER_AREA, 12);
		source.varbits.put(VarbitID.SLAYER_MASTER, 9);
		source.varbits.put(VarbitID.SLAYER_POINTS, 325);
		source.varbits.put(VarbitID.SLAYER_TASKS_COMPLETED, 64);
		source.taskRows.put(42, 4200);
		source.fields.put(key(4200, DBTableID.SlayerTask.COL_NAME_UPPERCASE), new Object[]{"Jellies"});
		source.areaRows.put(12, 1200);
		source.fields.put(key(1200, DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER), new Object[]{"Karuulm Slayer Dungeon"});

		Map<String, Object> snapshot = SlayerTaskSnapshot.build(source, OBSERVED_AT);
		Map<String, Object> task = (Map<String, Object>) snapshot.get("task");

		assertEquals(true, snapshot.get("taskLoaded"));
		assertEquals(false, snapshot.get("taskFromCache"));
		assertEquals(Instant.ofEpochMilli(OBSERVED_AT).toString(), snapshot.get("taskLastSeenTimestamp"));
		assertEquals("live", snapshot.get("status"));
		assertEquals(325, snapshot.get("points"));
		assertEquals(64, snapshot.get("streak"));
		assertEquals("Jellies", task.get("monster"));
		assertEquals(87, task.get("remaining"));
		assertEquals(143, task.get("original"));
		assertEquals(9, task.get("assignedById"));
		assertEquals("Karuulm Slayer Dungeon", task.get("requiredLocation"));
		assertEquals(true, task.get("identityKnown"));
	}

	@Test
	public void noAssignmentIsKnownWithoutInventingAMonster()
	{
		Map<String, Object> snapshot = SlayerTaskSnapshot.build(new FakeSource(), OBSERVED_AT);
		assertEquals(true, snapshot.get("taskLoaded"));
		assertEquals("none", snapshot.get("status"));
		assertNull(snapshot.get("task"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void unknownDatabaseRowsKeepTheLiveCountButNotAnInventedIdentity()
	{
		FakeSource source = new FakeSource();
		source.varps.put(VarPlayerID.SLAYER_COUNT, 10);
		source.varps.put(VarPlayerID.SLAYER_COUNT_ORIGINAL, 10);
		source.varps.put(VarPlayerID.SLAYER_TARGET, 999);
		Map<String, Object> task = (Map<String, Object>) SlayerTaskSnapshot.build(source, OBSERVED_AT).get("task");
		assertNull(task.get("monster"));
		assertEquals(false, task.get("identityKnown"));
	}

	@Test
	public void unavailableVarsRemainExplicitlyUnavailable()
	{
		FakeSource source = new FakeSource();
		source.fail = true;
		Map<String, Object> snapshot = SlayerTaskSnapshot.build(source, OBSERVED_AT);
		assertEquals(false, snapshot.get("taskLoaded"));
		assertEquals("unavailable", snapshot.get("status"));
		assertNull(snapshot.get("taskLastSeenTimestamp"));
		assertNull(snapshot.get("task"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void bossAssignmentsResolveThroughTheOfficialSubtable()
	{
		FakeSource source = new FakeSource();
		source.varps.put(VarPlayerID.SLAYER_COUNT, 25);
		source.varps.put(VarPlayerID.SLAYER_COUNT_ORIGINAL, 35);
		source.varps.put(VarPlayerID.SLAYER_TARGET, 98);
		source.varbits.put(VarbitID.SLAYER_TARGET_BOSSID, 7);
		source.bossRows.put(7, 7000);
		source.fields.put(key(7000, DBTableID.SlayerTaskSublist.COL_TASK), new Object[]{7100});
		source.fields.put(key(7100, DBTableID.SlayerTask.COL_NAME_UPPERCASE), new Object[]{"Vorkath"});
		Map<String, Object> task = (Map<String, Object>) SlayerTaskSnapshot.build(source, OBSERVED_AT).get("task");
		assertEquals("Vorkath", task.get("monster"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void stripsMarkupAndControlCharactersFromGameLabels()
	{
		FakeSource source = new FakeSource();
		source.varps.put(VarPlayerID.SLAYER_COUNT, 1);
		source.varps.put(VarPlayerID.SLAYER_COUNT_ORIGINAL, 1);
		source.varps.put(VarPlayerID.SLAYER_TARGET, 1);
		source.taskRows.put(1, 100);
		source.fields.put(key(100, DBTableID.SlayerTask.COL_NAME_UPPERCASE), new Object[]{"<col=red>Jelly\n"});
		Map<String, Object> task = (Map<String, Object>) SlayerTaskSnapshot.build(source, OBSERVED_AT).get("task");
		assertEquals("Jelly", task.get("monster"));
		assertFalse(((String) task.get("monster")).contains("<"));
	}

	private static String key(int row, int column)
	{
		return row + ":" + column;
	}

	private static final class FakeSource implements SlayerTaskSnapshot.Source
	{
		private final Map<Integer, Integer> varps = new HashMap<>();
		private final Map<Integer, Integer> varbits = new HashMap<>();
		private final Map<Integer, Integer> taskRows = new HashMap<>();
		private final Map<Integer, Integer> bossRows = new HashMap<>();
		private final Map<Integer, Integer> areaRows = new HashMap<>();
		private final Map<String, Object[]> fields = new HashMap<>();
		private boolean fail;

		@Override
		public int varp(int id)
		{
			if (fail)
			{
				throw new IllegalStateException("not logged in");
			}
			return varps.getOrDefault(id, 0);
		}

		@Override
		public int varbit(int id)
		{
			return varbits.getOrDefault(id, 0);
		}

		@Override
		public List<Integer> rowsByValue(int tableId, int columnId, int tupleIndex, Object value)
		{
			Map<Integer, Integer> rows = tableId == DBTableID.SlayerTask.ID
				? taskRows
				: tableId == DBTableID.SlayerTaskSublist.ID ? bossRows : areaRows;
			Integer row = rows.get(value);
			return row == null ? Collections.emptyList() : Collections.singletonList(row);
		}

		@Override
		public Object[] field(int rowId, int columnId, int tupleIndex)
		{
			return fields.get(key(rowId, columnId));
		}
	}
}
